#!/usr/bin/env python3
"""Extract per-day Entire Brain usage from Claude Code transcripts.

Both routes count: the MCP tools (mcp__entire-brain__*) and the CLI through
Bash (`entire brain <verb>`). Only lines that already contain a marker are
JSON-parsed -- the transcript corpus is gigabytes and parsing every line would
dominate the runtime.

Two things that are easy to get wrong here, both found by running it:

1. `entire-brain` also appears as a DIRECTORY (~/devenv/entire-brain), so a
   naive "word after the match" grabs the next shell word and reports verbs
   like `echo` and `git`. Hence the allowlist: a token only counts when it is
   a verb the binary actually registers.
2. A file's mtime bounds the scan safely (a file last written before the window
   cannot hold events inside it), but a file written today may carry months of
   history -- so every matching line is still date-checked on its own timestamp.

Empty answers are the point of this view, not a footnote: an empty result that
nobody notices is how a brain quietly stops being consulted while everyone
still believes it works. Results are paired back to their call by tool_use id.
"""
import json, os, re, sys, time, glob
from collections import defaultdict

DAYS = int(sys.argv[1]) if len(sys.argv) > 1 else 31
ROOT = os.path.expanduser("~/.claude/projects")

VERBS = {
    "add","agent-guide","bench","brief","bundle","capabilities","config","dash",
    "distill","doctor","entities","facts","gc","get","init-agents","inspect",
    "mcp","memory","multi-get","overview","path","patterns","privacy","publish",
    "query","recall","refresh","remember","repair","repo-identity","reset",
    "setup","show","stats","status","verify","version","viz","watch","workspace",
}

now = time.time()
window_start = time.strftime("%Y-%m-%d", time.localtime(now - (DAYS - 1) * 86400))
MARK_CALL = (b"entire-brain", b"entire brain")
MCP_RE = re.compile(r"mcp__entire-brain__([a-z_]+)")
# `entire` as a COMMAND, not as a path segment: reject a preceding / or word char.
BASH_RE = re.compile(r"(?<![\w/.-])entire(?:-brain|\s+brain)\s+([a-z][a-z-]*)")

days = defaultdict(lambda: {"mcp": 0, "bash": 0, "answered": 0, "empty": 0,
                            "failed": 0, "tools": defaultdict(int)})
scanned = matched = 0


def classify(payload: str):
    """answered | empty | unknown, from a brain reply body."""
    try:
        obj = json.loads(payload)
    except Exception:
        low = payload.lower()
        if "no facts for" in low or "nothing matched" in low or "no results" in low:
            return "empty"
        return "answered" if payload.strip() else "empty"
    if isinstance(obj, dict):
        if obj.get("blind_spot"):
            return "empty"
        for key in ("results", "facts", "items", "records", "matches"):
            val = obj.get(key)
            if isinstance(val, list):
                return "answered" if val else "empty"
        if obj.get("missing"):
            return "empty"
    if isinstance(obj, list):
        return "answered" if obj else "empty"
    return "answered"


def payload_text(c):
    content = c.get("content")
    if isinstance(content, str):
        return content
    if isinstance(content, list):
        return "".join(p.get("text", "") for p in content
                       if isinstance(p, dict) and p.get("type") == "text")
    if isinstance(content, dict):
        return content.get("stdout") or content.get("text") or ""
    return ""


for path in glob.glob(os.path.join(ROOT, "*", "*.jsonl")):
    try:
        if os.path.getmtime(path) < now - DAYS * 86400:
            continue
    except OSError:
        continue
    scanned += 1
    pending = {}          # tool_use id -> (day, verb)
    try:
        with open(path, "rb") as fh:
            for raw in fh:
                has_mark = any(m in raw for m in MARK_CALL)
                hit_id = None
                if pending and b'"tool_use_id"' in raw:
                    for tid in pending:
                        if tid.encode() in raw:
                            hit_id = tid
                            break
                if not has_mark and hit_id is None:
                    continue
                try:
                    obj = json.loads(raw)
                except Exception:
                    continue
                ts = obj.get("timestamp")
                if not isinstance(ts, str) or len(ts) < 10 or ts[:10] < window_start:
                    continue
                day = ts[:10]
                content = (obj.get("message") or {}).get("content")
                if not isinstance(content, list):
                    continue
                for c in content:
                    if not isinstance(c, dict):
                        continue
                    kind = c.get("type")
                    if kind == "tool_use":
                        name = c.get("name") or ""
                        m = MCP_RE.search(name)
                        verb = None
                        route = None
                        if m:
                            verb, route = m.group(1).replace("brain_", ""), "mcp"
                        elif name == "Bash":
                            bm = BASH_RE.search(str((c.get("input") or {}).get("command") or ""))
                            if bm and bm.group(1) in VERBS:
                                verb, route = bm.group(1), "bash"
                        if verb:
                            days[day][route] += 1
                            days[day]["tools"][verb] += 1
                            matched += 1
                            if c.get("id"):
                                pending[c["id"]] = (day, verb)
                                if len(pending) > 400:
                                    pending.pop(next(iter(pending)))
                    elif kind == "tool_result":
                        tid = c.get("tool_use_id")
                        if tid not in pending:
                            continue
                        d, _verb = pending.pop(tid)
                        if c.get("is_error"):
                            days[d]["failed"] += 1
                        else:
                            days[d][classify(payload_text(c))
                                     if classify(payload_text(c)) != "unknown"
                                     else "answered"] += 1
    except OSError:
        continue

json.dump({
    "generated_at": time.strftime("%Y-%m-%dT%H:%M:%SZ", time.gmtime()),
    "window_days": DAYS,
    "window_start": window_start,
    "files_scanned": scanned,
    "events": matched,
    "days": {d: {"mcp": v["mcp"], "bash": v["bash"], "answered": v["answered"],
                 "empty": v["empty"], "failed": v["failed"],
                 "tools": dict(sorted(v["tools"].items(), key=lambda kv: -kv[1]))}
             for d, v in sorted(days.items())},
}, sys.stdout, indent=1)
