export function register(on) {
  on('session.start', async ($, e, next) => {
    await $.command.register({
      name: 'brain-memory',
      description: 'What Entire Brain contributed to this session',
    })
    return next(e)
  })

  // Group by turn, so "what did brain give me for THIS question" is answerable.
  on('turn.start', async ($, e, next) => {
    await update($, turnNo, (n) => n + 1)
    return next(e)
  })

  on('tool.call', async ($, e, next) => {
    const call = brainCallOf(e)

    // The tool runs either way: this mod observes and never changes a call.
    const result = await next(e)
    if (!call) return result

    // When Claude Code truncated the output it keeps the whole thing in a
    // file. Read that, so a 39 KB brain answer is classified from the payload
    // rather than from the fragment that survived truncation.
    let fullText = ''
    const persisted = result?.result?.persistedOutputPath
    if (typeof persisted === 'string' && persisted.trim()) {
      try {
        const read = await $.fs.read(persisted)
        if (typeof read === 'string') fullText = read
      } catch {
        /* classify from the truncated text instead */
      }
    }

    const { outcome, detail, note } = summarize(result, fullText)
    const turn = await read($, turnNo)
    // Writing state redraws the sites that read it, so no invalidate here.
    await update($, calls, (list) => [{ turn, ...call, outcome, detail, note }, ...list].slice(0, MAX_ENTRIES))

    // An empty answer is the one worth interrupting for, and the note explains
    // it. Capped, because a mod that floods the transcript gets uninstalled.
    if (outcome !== 'hit' && logged < 20) {
      logged += 1
      $.ui.log('brain ' + call.verb + ': ' + detail + (note ? ' — ' + note : ''))
    }
    return result
  })

  on('command.run', { command: 'brain-memory' }, async ($) => {
    await $.ui.open({ id: PANE, title: 'Brain memory', focus: true, closeOnEscape: true })
    return {}
  })

  // A count beside the spinner, so the pane is discoverable without docs: you
  // notice brain was consulted, then open it to see what it actually said.
  on('ui.render', { component: 'Spinner' }, async ($, e, next) => {
    const entries = await read($, calls)
    if (entries.length === 0) return next(e)
    const { hit, empty, error } = tally(entries)
    const parts = [hit + ' answered']
    if (empty > 0) parts.push(empty + ' empty')
    if (error > 0) parts.push(error + ' failed')
    return next({ ...e, props: { ...e.props, suffix: ' · brain ' + parts.join(', ') + '…' } })
  })

  on('ui.render', { component: 'Pane' }, async ($, e, next) => {
    if (e.requestId !== PANE) return next(e)
    const { Box, Text } = $.ui.resolve(e)
    const width = Math.max(28, Number(e.props?.bodyColumns) || 60)
    const entries = await read($, calls)
    const turn = await read($, turnNo)

    if (entries.length === 0) {
      return Box({
        flexDirection: 'column',
        children: [
          Text({ bold: true, children: ['Brain memory'] }),
          Text({ children: [' '] }),
          // Counting starts when the module loads, and `register` runs again on
          // every reload, so the module's variables start over. Saying "none
          // this session" would overclaim: calls made before the mod loaded are
          // invisible to it, and claiming otherwise is the same kind of
          // confident-but-wrong empty answer this pane exists to catch.
          Text({ dimColor: true, wrap: 'wrap', children: ['No brain call since this pane started watching (it counts from when the mod first loaded in this session).'] }),
          Text({
            dimColor: true,
            wrap: 'wrap',
            children: ['If the agent is not reaching for brain at all, it may not know it exists — run `entire brain init-agents` in this repo.'],
          }),
        ],
      })
    }

    const { hit, empty, error } = tally(entries)
    const header = [
      Text({ bold: true, children: ['Brain memory'] }),
      Text({ color: 'green', children: [hit + ' answered'] }),
      empty > 0
        ? Text({ color: 'yellow', children: [empty + ' empty'] })
        : Text({ dimColor: true, children: ['0 empty'] }),
    ]
    if (error > 0) header.push(Text({ color: 'red', children: [error + ' failed'] }))

    const rows = []
    let shown = null
    let turnsShown = 0
    for (const x of entries) {
      if (x.turn !== shown) {
        turnsShown += 1
        if (turnsShown > MAX_TURNS) break
        shown = x.turn
        const label = x.turn === turn ? 'this turn' : 'turn ' + x.turn
        rows.push(Text({ dimColor: true, children: [label + ' ' + '─'.repeat(Math.max(1, width - label.length - 1))] }))
      }
      rows.push(
        Box({
          flexDirection: 'row',
          columnGap: 1,
          children: [
            Text({ color: COLOR[x.outcome], children: [MARK[x.outcome]] }),
            Text({ bold: true, children: [x.verb] }),
            Text({ wrap: 'truncate-end', children: [x.query || '—'] }),
            Text({ dimColor: true, children: ['(' + x.detail + ')'] }),
          ],
        }),
      )
      // Brain knows why it had nothing. This is the only place it gets said out loud.
      if (x.note && x.outcome !== 'hit') {
        rows.push(Text({ color: 'yellow', wrap: 'wrap', children: ['  ' + x.note] }))
      }
    }

    return Box({
      flexDirection: 'column',
      children: [
        Box({ flexDirection: 'row', columnGap: 2, children: header }),
        Text({ children: [' '] }),
        ...rows,
      ],
    })
  })
}

