// runs quiet-to-hot. A day with nothing is dim, never coloured: a zero that is
// given a colour reads as a value, which is the mistake this whole mod is about.
const RAMP = ['blue', 'cyan', 'green', 'yellow', 'red']
const BARS = ['▁', '▂', '▃', '▅', '▆', '▇', '█']
const CELL = '██'
const EMPTY_CELL = '··'

function bucket(n, max) {
  if (!n) return -1
  if (max <= 0) return 0
  return Math.min(RAMP.length - 1, Math.max(0, Math.ceil((n / max) * RAMP.length) - 1))
