  if (!n) return '·'
  if (max <= 0) return BARS[0]
  return BARS[Math.min(BARS.length - 1, Math.max(0, Math.ceil((n / max) * BARS.length) - 1))]
}

// The collector reports only days that HAVE events. The chart needs every day in
// the window, zeros included -- a chart that silently omits quiet days makes a
// gap look like continuous use.
function windowDays(data) {
  const out = []
  const start = Date.parse((data?.window_start || '') + 'T00:00:00Z')
  const span = Number(data?.window_days) || DEFAULT_DAYS
  if (!Number.isFinite(start)) return out
  for (let i = 0; i < span; i += 1) {
    const date = new Date(start + i * 86400000)
    const key = date.toISOString().slice(0, 10)
    const row = data?.days?.[key] || null
    out.push({
      key,
      date,
      total: row ? (row.mcp || 0) + (row.bash || 0) : 0,
      mcp: row ? row.mcp || 0 : 0,
